 }
diff --git a/src/test/java/hotel/web/HttpApiTest.java b/src/test/java/hotel/web/HttpApiTest.java
index f9a3f6f..03e6792 100644
--- a/src/test/java/hotel/web/HttpApiTest.java
+++ b/src/test/java/hotel/web/HttpApiTest.java
@@ -119,4 +119,55 @@ class HttpApiTest {
         assertEquals(400, get("/reports/revenue?month=july").statusCode());
         assertEquals(400, get("/reports/occupancy").statusCode());
     }
+
+    @Test
+    void childrenIsOptionalAndAppearsInTheResponse() throws Exception {
+        String withoutChildren = """
+                {"roomNumber": 101, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
+                 "guestCpf": "111.222.333-44", "checkIn": "2027-07-10", "checkOut": "2027-07-12",
+                 "guests": 2, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> created = post("/reservations", withoutChildren);
+        assertEquals(201, created.statusCode());
+        JsonNode reservation = json.readTree(created.body());
+        assertEquals(0, reservation.get("children").asInt());
+
+        String withChildren = """
+                {"roomNumber": 102, "guestName": "João Silva", "guestEmail": "joao@example.com",
+                 "guestCpf": "111.222.333-45", "checkIn": "2027-07-10", "checkOut": "2027-07-12",
+                 "guests": 1, "children": 1, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> createdWithChildren = post("/reservations", withChildren);
+        assertEquals(201, createdWithChildren.statusCode());
+        JsonNode reservationWithChildren = json.readTree(createdWithChildren.body());
+        assertEquals(1, reservationWithChildren.get("children").asInt());
+
+        long id = reservationWithChildren.get("id").asLong();
+        JsonNode fetched = json.readTree(get("/reservations/" + id).body());
+        assertEquals(1, fetched.get("children").asInt());
+    }
+
+    @Test
+    void childrenCannotBeNegative() throws Exception {
+        String negativeChildren = """
+                {"roomNumber": 101, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
+                 "guestCpf": "111.222.333-44", "checkIn": "2027-07-10", "checkOut": "2027-07-12",
+                 "guests": 2, "children": -1, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> response = post("/reservations", negativeChildren);
+        assertEquals(400, response.statusCode());
+        assertEquals("INVALID_REQUEST", json.readTree(response.body()).get("error").asText());
+    }
+
+    @Test
+    void adultsAndChildrenCannotExceedCapacity() throws Exception {
+        String exceedsCapacity = """
+                {"roomNumber": 101, "guestName": "Carla Dias", "guestEmail": "carla@example.com",
+                 "guestCpf": "111.222.333-44", "checkIn": "2027-07-10", "checkOut": "2027-07-12",
+                 "guests": 1, "children": 2, "ratePlan": "STANDARD"}
+                """;
+        HttpResponse<String> response = post("/reservations", exceedsCapacity);
+        assertEquals(422, response.statusCode());
+        assertEquals("CAPACITY_EXCEEDED", json.readTree(response.body()).get("error").asText());
+    }
 }
